def H_(i,t,d,ref): return {'id':i,'t':t,'d':d,'kind':'حديث','ref':ref}
KH='كما فهمه السعدي. وأحكام الجماعة التفصيلية وخلاف المذاهب فيها في تبويب الخلاف.'
add={
'fitr':[('why',H_('m1','الحكمة في نص الحديث','عن ابن عباس: فرض رسول الله ﷺ زكاة الفطر طهرة للصائم من اللغو والرفث وطعمة للمساكين، من أداها قبل الصلاة فهي زكاة مقبولة، ومن أداها بعد الصلاة فهي صدقة من الصدقات. فالحديث نفسه يذكر غرضين: تطهير الصائم مما وقع منه في صومه من اللغو والرفث، وإطعام المساكين.','أبو داود (2357 هو للفطر؛ هذا الحديث رقمه 1609). درجته على sunnah.com: حسن (الألباني). https://sunnah.com/abudawud:1609')),
        ('why',S_('m2','قد أفلح من تزكى','قال تعالى: قد أفلح من تزكى وذكر اسم ربه فصلى. قال السعدي: أي فاز من طهر نفسه ونقاها من الشرك والظلم ومساوئ الأخلاق، وذكر اسم ربه بأن اتصف بذكر الله وانصبغ به قلبه فأوجب له العمل بما يرضي الله خصوصاً الصلاة. وذكر أن من فسر ﴿تزكى﴾ بإخراج زكاة الفطر و﴿فصلى﴾ بصلاة العيد، فهذا داخل في اللفظ وبعض جزئياته وليس هو المعنى وحده.',K%(87,14)+' و '+K%(87,15)))],
'siyam2':[('why',S_('m1','وأن تصوموا خير لكم','قال تعالى: وأن تصوموا خير لكم إن كنتم تعلمون. وقال السعدي في سياق آية الفدية: كان الصيام في ابتداء فرضه شاقاً على من لم يعتده، فدرجهم الله بأسهل طريق، وخير المطيق بين أن يصوم وهو أفضل أو يطعم. وهذا في بيان فضل الصوم على الفدية في مبتدأ الفرض، وليس حكماً في صوم التطوع.',K%(2,184)))],
'itikaf':[('why',S_('m1','لزوم المسجد انقطاعاً إلى الله','قال السعدي في تفسير ﴿وأنتم عاكفون في المساجد﴾: الاعتكاف لزوم المسجد لطاعة الله تعالى وانقطاعاً إليه. وفي آية البيت: قال تعالى ﴿أن طهرا بيتي للطائفين والعاكفين والركع السجود﴾، وذكر السعدي أن الاعتكاف قدم بعد الطواف لأن من شرطه المسجد مطلقاً، ثم ذكر الصلاة. وما ذكره من شروط في صحة الاعتكاف رأي له، وتفصيل المذاهب في الاعتكاف في تبويب الخلاف.',K%(2,187)+' و '+K%(2,125)))],
'sadaqa':[('symbols',S_('m3','الإسرار والإعلان','قال تعالى: إن تبدوا الصدقات فنعما هي وإن تخفوها وتؤتوها الفقراء فهو خير لكم ويكفر عنكم من سيئاتكم. وقال السعدي: صدقة السر على الفقير أفضل من العلانية، وأما إن لم تؤت الفقراء فمفهوم الآية أن السر ليس خيراً من العلانية فيرجع في ذلك إلى المصلحة، فإن كان في إظهارها إظهار شعائر الدين وحصول الاقتداء فهو أفضل. وفي قوله ﴿وتؤتوها الفقراء﴾ أنه ينبغي للمتصدق أن يتحرى المحتاجين.',K%(2,271))),
          ('symbols',S_('m4','الصدقة في كل الأوقات','قال تعالى: الذين ينفقون أموالهم بالليل والنهار سراً وعلانية فلهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون. قال السعدي: ذكر حالة المتصدقين في جميع الأوقات وعلى جميع الأحوال، والإنفاق في سبيل الله أي في طاعته وطريق مرضاته لا في المحرمات والمكروهات وشهوات النفوس.',K%(2,274)))],
'sahw':[('why',H_('m1','ترغيماً للشيطان','في حديث أبي سعيد الخدري: إذا شك أحدكم في صلاته فلم يدر كم صلى ثلاثاً أم أربعاً فليطرح الشك وليبن على ما استيقن، ثم يسجد سجدتين قبل أن يسلم، فإن كان صلى خمساً شفعن له صلاته، وإن كان صلى إتماماً لأربع كانتا ترغيماً للشيطان. فنص الحديث على أثر السجدتين في الحالتين.','مسلم (571أ). https://sunnah.com/muslim:571a'))],
'arkan':[('why',S_('m2','الخشوع روح الصلاة','قال تعالى: الذين هم في صلاتهم خاشعون. قال السعدي: الخشوع في الصلاة حضور القلب بين يدي الله مستحضراً قربه، فيسكن لذلك قلبه وتطمئن نفسه وتسكن حركاته ويقل التفاته متأدباً بين يدي ربه مستحضراً جميع ما يقوله ويفعله من أول صلاته إلى آخرها. وقال: هذا روح الصلاة والمقصود منها وهو الذي يكتب للعبد، والصلاة التي لا خشوع فيها وإن كانت مجزئة مثاباً عليها فإن الثواب على حسب ما يعقل القلب منها.',K%(23,2)))],
'shurut':[('why',S_('m2','ما تثمره الصلاة التامة','قال تعالى: إن الصلاة تنهى عن الفحشاء والمنكر. وقال السعدي في وجه ذلك: إن العبد المقيم لها، المتمم لأركانها وشروطها وخشوعها، يستنير قلبه ويتطهر فؤاده ويزداد إيمانه وتقوى رغبته في الخير وتقل أو تعدم رغبته في الشر، فمداومتها والمحافظة عليها على هذا الوجه تنهى عن الفحشاء والمنكر.',K%(29,45)))],
'wajibat':[('why',S_('m2','المحافظة على الصلوات','قال تعالى: حافظوا على الصلوات والصلاة الوسطى وقوموا لله قانتين. قال السعدي: المحافظة عليها أداؤها بوقتها وشروطها وأركانها وخشوعها وجميع ما لها من واجب ومستحب، وبالمحافظة عليها تحصل المحافظة على سائر العبادات.',K%(2,238)))],
'sunan1':[('why',S_('m2','المحافظة على الصلوات','قال تعالى: حافظوا على الصلوات والصلاة الوسطى وقوموا لله قانتين. قال السعدي: المحافظة عليها أداؤها بوقتها وشروطها وأركانها وخشوعها وجميع ما لها من واجب ومستحب. فيدخل في كلامه الواجب والمستحب معاً، وأحكام كل سنة وخلاف المذاهب فيها في تبويب الخلاف.',K%(2,238)))],
'makruhat1':[('why',S_('m1','الخشوع وقلة الالتفات وسكون الحركات','قال السعدي في تفسير ﴿في صلاتهم خاشعون﴾: الخشوع حضور القلب بين يدي الله، فيسكن القلب وتطمئن النفس وتسكن الحركات ويقل الالتفات متأدباً بين يدي ربه. وهذا وصف للخشوع كما ذكره، وليس نصاً في كل مكروه من مكروهات الصلاة.',K%(23,2)))],
'makruhat2':[('why',S_('m1','الخشوع وقلة الالتفات وسكون الحركات','قال السعدي في تفسير ﴿في صلاتهم خاشعون﴾: الخشوع حضور القلب بين يدي الله، فيسكن القلب وتطمئن النفس وتسكن الحركات ويقل الالتفات متأدباً بين يدي ربه. وهذا وصف للخشوع كما ذكره، وليس نصاً في كل مكروه من مكروهات الصلاة.',K%(23,2)))],
'jumua1':[('why',S_('m1','السعي إلى ذكر الله','قال تعالى: يا أيها الذين آمنوا إذا نودي للصلاة من يوم الجمعة فاسعوا إلى ذكر الله وذروا البيع ذلكم خير لكم إن كنتم تعلمون. قال السعدي: السعي هنا المبادرة والاهتمام لها وجعلها أهم الأشغال، لا العدو الذي نهي عنه عند المضي إلى الصلاة. وقال: ترك البيع مؤقت مدة الصلاة، ومن آثر الدنيا على الدين فقد خسر الخسارة الحقيقية.',K%(62,9))),
          ('why',S_('m2','فانتشروا في الأرض واذكروا الله','قال تعالى: فإذا قضيت الصلاة فانتشروا في الأرض وابتغوا من فضل الله واذكروا الله كثيراً لعلكم تفلحون. قال السعدي: لما كان الاشتغال بالتجارة مظنة الغفلة عن ذكر الله أمر الله بالإكثار من ذكره، وهو أكبر أسباب الفلاح.',K%(62,10)))],
'jamaa1':[('why',S_('m1','واركعوا مع الراكعين','قال تعالى: وأقيموا الصلاة وآتوا الزكاة واركعوا مع الراكعين. قال السعدي: أي صلوا مع المصلين، وفهم من الآية الأمر بالجماعة ووجوبها. وهذا فهمه هو لها، وقد اختلف الفقهاء في حكم الجماعة، ويبين تبويب الخلاف أقوال المذاهب. وذكر أن الأمر بالركوع يدل على أن الركوع ركن لأنه عبر عن الصلاة بجزئها.',K%(2,43)))],
'safar1':[('why',S_('m1','رخصة القصر','قال تعالى: وإذا ضربتم في الأرض فليس عليكم جناح أن تقصروا من الصلاة. قال السعدي: الآية أصل في رخصة القصر وصلاة الخوف، وقال إن الرخصة سهولة من الله لعباده إذا سافروا أن يقصروا ويفطروا. وذكر أن نفي الحرج لا ينافي كون القصر هو الأفضل ولا ينافي الوجوب، وأن ظاهر الآية الترخص في أي سفر كما هو مذهب أبي حنيفة، وخالفه الجمهور في سفر المعصية. وتفصيل المذاهب في تبويب الخلاف.',K%(4,101)))],
'qiyam':[('why',S_('m2','ناشئة الليل','قال تعالى: إن ناشئة الليل هي أشد وطئاً وأقوم قيلاً. قال السعدي: هذا بيان للحكمة في الأمر بقيام الليل، والمراد الصلاة فيه بعد النوم، وهي أقرب إلى تحصيل مقصود القرآن، يتواطأ على القرآن القلب واللسان وتقل الشواغل ويفهم ما يقول، وهذا بخلاف النهار.',K%(73,6))),
         ('why',S_('m3','تتجافى جنوبهم عن المضاجع','قال تعالى: تتجافى جنوبهم عن المضاجع يدعون ربهم خوفاً وطمعاً. قال السعدي: أي ترتفع جنوبهم عن مضاجعها اللذيذة إلى ما هو ألذ عندهم وأحب إليهم وهو الصلاة في الليل ومناجاة الله، ويدعون ربهم جامعين بين الخوف من رد أعمالهم والطمع في قبولها.',K%(32,16)))],
'tarawih':[('why',S_('m1','قيام الليل في القرآن','قال السعدي في تفسير ﴿إن ناشئة الليل هي أشد وطئاً وأقوم قيلاً﴾: الصلاة في الليل بعد النوم أقرب إلى تحصيل مقصود القرآن، يتواطأ على القرآن القلب واللسان وتقل الشواغل. وهذا كلام في قيام الليل عموماً وليس خاصاً بالتراويح.',K%(73,6)))],
'tatawwu':[('why',S_('m1','تتجافى جنوبهم عن المضاجع','قال تعالى: تتجافى جنوبهم عن المضاجع يدعون ربهم خوفاً وطمعاً. قال السعدي: أي ترتفع جنوبهم عن مضاجعها اللذيذة إلى ما هو ألذ عندهم وهو الصلاة في الليل ومناجاة الله. وهذا في صلاة الليل خاصة.',K%(32,16)))],
'naflhajj':[('why',S_('m1','مثابة للناس','قال تعالى: وإذ جعلنا البيت مثابة للناس وأمناً. قال السعدي: أي مرجعاً يثوبون إليه لحصول منافعهم الدينية والدنيوية، يترددون إليه ولا يقضون منه وطراً. وفي هذا المعنى بيان لسبب تكرر قصد البيت عند الناس، وأحكام تكرار الحج والعمرة وتفضيله على غيره في تبويب الخلاف.',K%(2,125)))],
}
cnt=0
for C in W:
  for L in C['lessons']:
    if L['id'] in add:
      ids={x['id'] for g in L['meaning'].values() for x in g}
      for g,it in add[L['id']]:
        if it['id'] in ids:
          n=max(int(i[1:]) for i in ids)+1; it['id']='m%d'%n
        ids.add(it['id']); L['meaning'][g].append(it); cnt+=1
lib.save(head,W,R,S);print(cnt)
